withLabelsCode.vanilla:
// Cinco moldes e as quatro palavras, e todos são de interface — nenhum deles é
// a fala do agente.
//
// O NOME DA CAMADA QUE ROLA é obrigatório: a cascata é mais larga que a
// conversa, então ela rola, e o que rola é parada de teclado. Sem nome, quem
// chega ali ouvindo não sabe onde entrou — e duas peças destas na mesma tela com
// o mesmo nome são duas paradas indistinguíveis.
//
// A RÉGUA DITA EM PALAVRAS é visível: sem ela, "todas as barras contra o mesmo
// eixo" é uma afirmação que só quem escreveu o dado consegue conferir.
//
// A LEITURA leva a posição em números a quem não vê a barra, e a FRASE DO
// RECORTE avisa que o trecho continua fora da janela mostrada.
const rotulos = {
  region: 'Tempo do atendimento',
  axis: 'Eixo de {total} ms',
  duration: '{duration} ms',
  reading: 'Começa em {start} ms e dura {duration} ms.',
  clipped: 'Continua fora da janela mostrada.',
  state: {
    pending: 'Por começar',
    running: 'Em andamento',
    done: 'Concluído',
    failed: 'Falhou',
  },
};

