extensibilityCode.vanilla:
// REVELAR É PASSAR MENOS TRECHOS, e não existe contador de revelação na peça.
//
// O EIXO CONTINUA O MESMO, e é isso que faz a revelação funcionar: as barras que
// sobraram guardam a posição verdadeira em vez de reescalarem para ocupar a
// régua inteira. Quem quiser a entrada animada resolve na folha de animação, que
// é a dona do assunto — o componente desenha o que recebe.
let revelados = 1;

function revelar() {
  revelados += 1;
  const proxima = createTraceWaterfall({
    spans: trechos.slice(0, revelados),
    totalMs: 1200,
    status: revelados >= trechos.length ? 'complete' : 'running',
    labels: rotulos,
  });
  if (proxima) cascata.replaceWith(proxima);
}

extensibilityCode.react:
// REVELAR É PASSAR MENOS TRECHOS, e não existe contador de revelação na peça.
//
// O EIXO CONTINUA O MESMO, e é isso que faz a revelação funcionar: as barras que
// sobraram guardam a posição verdadeira em vez de reescalarem para ocupar a
// régua inteira. Quem quiser a entrada animada resolve na folha de animação, que
// é a dona do assunto — o componente desenha o que recebe.
const [revelados, setRevelados] = useState(1);

const revelar = () => setRevelados((atual) => Math.min(atual + 1, trechos.length));

<TraceWaterfall
  spans={trechos.slice(0, revelados)}
  totalMs={1200}
  status={revelados >= trechos.length ? "complete" : "running"}
  labels={rotulos}
/>

extensibilityCode.angular:
// REVELAR É PASSAR MENOS TRECHOS, e não existe contador de revelação na peça.
//
// O EIXO CONTINUA O MESMO, e é isso que faz a revelação funcionar: as barras que
// sobraram guardam a posição verdadeira em vez de reescalarem para ocupar a
// régua inteira. Quem quiser a entrada animada resolve na folha de animação, que
// é a dona do assunto — o componente desenha o que recebe.
//
// TUDO É MEMBRO DE CLASSE, e nenhum deles é constante no topo do arquivo:
// expressão de template só enxerga membro, e um binding para uma constante
// importada não resolve.
readonly trechos: readonly TraceSpan[] = [/* os trechos do rastro */];

readonly revelados = signal(1);

readonly visiveis = computed(() => this.trechos.slice(0, this.revelados()));

readonly estado = computed<RunStatus>(() =>
  this.revelados() >= this.trechos.length ? 'complete' : 'running',
);

revelar(): void {
  this.revelados.update((atual) => Math.min(atual + 1, this.trechos.length));
}

// No template, os quatro entram como os membros que são:
//
//   <div
//     ndsTraceWaterfall
//     [spans]="visiveis()"
//     [totalMs]="1200"
//     [status]="estado()"
//     [labels]="rotulos"
//   ></div>

customizationCode.web:
.nds-trace-waterfall {
  /* As duas larguras MÍNIMAS, e são elas que decidem quando a cascata passa a
     ser mais larga que a conversa e a camada começa a rolar. Mínimas e não
     fixas: a coluna do nome cresce com o rótulo mais longo e a do eixo reparte
     o que sobrar. */
  --trace-waterfall-name-min: var(--spacing-16);
  --trace-waterfall-axis-min: var(--spacing-20);
}

